onRowSelected:
{{
  (function() {
    const row = Table_interventions.selectedRow;

    if (!row || row.isHeader === true) {
      return;
    }

    return storeValue('tab_atelier_actif', '🛠️ Atelier Global')
      .then(() => storeValue('page_precedente', '🛠️ Atelier'))
      .then(() => navigateTo('Détail Intervention', { id: row.ID_Intervention }));
  })()
}}

